async function authenticate(e){e.preventDefault();setAuthNotice('');try{let credential;if(authMode==='signup'){const cleanHandle=gppUsername.trim().replace(/^@/,'').replace(/\.GPP$/i,'').toLowerCase().replace(/[^a-z0-9._]/g,'');if(!cleanHandle)throw new Error('Escolha seu usuário GPP.');const handle='@'+cleanHandle+'.GPP';const taken=await getDocs(firestoreQuery(collection(firestore,'users'),where('usernameLower','==',handle.toLowerCase())));if(!taken.empty)throw new Error('Esse usuário GPP já está em uso. Escolha outro.');credential=await createUserWithEmailAndPassword(firebaseAuth,email.trim(),password);await (await import('firebase/auth')).updateProfile(credential.user,{displayName:profile.trim()});await addDoc(collection(firestore,'users'),{uid:credential.user.uid,username:handle,usernameLower:handle.toLowerCase(),displayName:profile.trim(),email:email.trim(),createdAt:serverTimestamp()});try{await sendEmailVerification(credential.user);setAuthNotice('Conta criada! Enviamos um e-mail para confirmar seu endereço. Confira também o spam.')}catch(verificationError){console.warn('Não foi possível enviar a confirmação:',verificationError)}}else{credential=await signInWithEmailAndPassword(firebaseAuth,email.trim(),password)}setUser(credential.user);if(authMode==='login'){setModal('');notify('Login realizado!')}else{setModal('');notify('Conta criada com sucesso!')}}catch(error){const messages={'auth/email-already-in-use':'Este e-mail já possui uma conta. Tente entrar.','auth/invalid-credential':'E-mail ou senha incorretos.','auth/weak-password':'A senha precisa ter pelo menos 6 caracteres.','auth/invalid-email':'Digite um endereço de e-mail válido.','auth/operation-not-allowed':'Ative E-mail/senha no Firebase Authentication.'};notify(messages[error.code]||error.message)}}
async function resendConfirmation(){if(!firebaseAuth.currentUser){notify('Entre na conta para reenviar a confirmação do e-mail.');return}try{await sendEmailVerification(firebaseAuth.currentUser);setAuthNotice('E-mail de confirmação reenviado. Confira sua caixa de entrada e o spam.');notify('Confirmação reenviada.')}catch(error){notify('Não foi possível reenviar: '+error.message)}}
