async function updateRecord(record,changes){if(!firebaseAuth.currentUser||!record?.id)throw new Error('Registro inválido ou sessão encerrada.');await updateDoc(doc(firestore,'projects',record.id),{...changes,updatedAt:serverTimestamp()});}
async function removeRecord(record){if(!firebaseAuth.currentUser||!record?.id)throw new Error('Registro inválido ou sessão encerrada.');await deleteDoc(doc(firestore,'projects',record.id));}
async function addProject(e){e.preventDefault();if(!newName.trim())return;if(!firebaseAuth.currentUser){notify('Entre na sua conta para salvar projetos.');return}const project={recordType:'project',name:newName.trim(),client:client.trim()||'Cliente novo',type:'Projeto · 0 arquivos',color:['violet','mint','amber','rose'][projects.length%4],progress:0,stage:'Briefing',date:'Agora'};try{const saved=await saveRecord(project);setProjects([{...project,id:saved.id},...projects]);setNewName('');setClient('');setModal('');go('projects');notify('Projeto salvo no Firebase.')}catch(error){console.error('Erro ao salvar projeto:',error);notify('Não foi possível salvar. Confira se o Cloud Firestore foi criado e se as regras estão configuradas.')}}
