function normalizeGpp(value){const clean=String(value||'').trim().replace(/^@/,'').replace(/\\.GPP$/i,'').toLowerCase().replace(/[^a-z0-9._]/g,'');return clean?'@'+clean+'.GPP':''}
async function sendProjectInvite(e){e.preventDefault();try{if(!firebaseAuth.currentUser)throw new Error('Entre na sua conta.');if(!inviteProjectId)throw new Error('Selecione o projeto que deseja compartilhar.');const handle=normalizeGpp(inviteUsername);if(!handle)throw new Error('Informe o usuário GPP.');if(handle.toLowerCase()===normalizeGpp(gppUsername).toLowerCase())throw new Error('Você não pode convidar sua própria conta.');const found=await getDocs(firestoreQuery(collection(firestore,'users'),where('usernameLower','==',handle.toLowerCase())));if(found.empty)throw new Error('Não encontramos esse usuário GPP. Confira o identificador.');const target=found.docs[0].data();const project=projects.find(p=>p.id===inviteProjectId);if(!project)throw new Error('Projeto não encontrado.');const already=(project.sharedUids||[]).includes(target.uid);if(project.ownerUid===target.uid||already)throw new Error('Esse profissional já tem acesso ao projeto.');const pending=await getDocs(firestoreQuery(collection(firestore,'invites'),where('recipientUid','==',target.uid)));if(pending.docs.some(d=>d.data().projectId===project.id&&d.data().status==='Pendente'))throw new Error('Já existe um convite pendente para esse projeto.');await addDoc(collection(firestore,'invites'),{ownerUid:firebaseAuth.currentUser.uid,ownerName:profile,recipientUid:target.uid,recipientUsername:target.username,projectId:project.id,projectName:project.name,permission:invitePermission,status:'Pendente',createdAt:serverTimestamp()});setModal('');setInviteUsername('');notify('Convite enviado para '+target.username+'.');}catch(error){notify(error.message||'Não foi possível enviar o convite.')}} 
async function respondInvite(invite,accept){try{if(accept){const ref=doc(firestore,'projects',invite.projectId);await updateDoc(ref,{sharedUids:arrayUnion(firebaseAuth.currentUser.uid),['memberRoles.'+firebaseAuth.currentUser.uid]:invite.permission,acceptedInviteId:invite.id,updatedAt:serverTimestamp()});}await updateDoc(doc(firestore,'invites',invite.id),{status:accept?'Aceito':'Recusado',respondedAt:serverTimestamp()});setInvites(prev=>prev.map(x=>x.id===invite.id?{...x,status:accept?'Aceito':'Recusado'}:x));if(accept){const own=await getDocs(firestoreQuery(collection(firestore,'projects'),where('ownerUid','==',firebaseAuth.currentUser.uid)));const shared=await getDocs(firestoreQuery(collection(firestore,'projects'),where('sharedUids','array-contains',firebaseAuth.currentUser.uid)));const merged=[...new Map([...own.docs,...shared.docs].map(d=>[d.id,{id:d.id,...d.data()}])).values()];setProjects(merged.filter(x=>!x.recordType||x.recordType==='project'));notify('Convite aceito. O projeto foi adicionado à sua conta.');}else notify('Convite recusado.');}catch(error){notify('Não foi possível responder ao convite: '+error.message)}}
